// ❌ BAD: Classic Cache-Aside causes stampede upon exact TTL expiry
public async Task<Product> GetProductAsync(string id) {
    var cached = await _redis.GetStringAsync(id);
    if (cached == null) {
        // 5,000 concurrent threads hit DB at the same millisecond!
        var product = await _db.Products.FindAsync(id);
        await _redis.SetStringAsync(id, product, TimeSpan.FromMinutes(10));
        return product;
    }
    return JsonSerializer.Deserialize<Product>(cached);
}

solutionSnippet:
// ✅ SENIOR PATTERN: Probabilistic Early Refresh (XFetch: delta * beta * ln(rnd))
public async Task<Product> GetProductAsync(string id) {
    var (data, deltaComputeMs, ttlRemainingSeconds) = await _redis.GetWithMetaAsync(id);

    // XFetch formula: If remaining TTL < delta * beta * -ln(random[0..1]), refresh early!
    double beta = 1.0; // aggressiveness factor
    double random = Random.Shared.NextDouble();

    if (data != null && -deltaComputeMs * beta * Math.Log(random) > ttlRemainingSeconds * 1000) {
        _ = Task.Run(async () => await RefreshCacheAsync(id)); // Background warm-up
    }
    return data ?? await RefreshCacheAsync(id);
}

